173	    /**
174	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
175	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
176	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
177	     * the sequence of create-time rejections stays readable and a new rule is added as one more
178	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
179	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
180	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
181	     * the household id has been resolved, because that key includes the household id.
182	     *
183	     * @param owner the newly mapped and normalized owner being created
184	     */
185	    private void rejectDisallowedOwnerCreation(Owner owner) {
186	        rejectWhenDailyLimitReached(owner);
187	        rejectWhenCityAtCapacity(owner);
188	    }
189	
190	    /**
191	     * Applies the household-membership rules for a newly normalized owner being created. It finds
192	     * the existing owners who share the owner's household (same last name and address, compared
193	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
194	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
195	     * the new owner and every existing member the same stable {@code householdId}; and records the
196	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
197	     * owner is rejected only when its whole identity key matches an existing owner (see
198	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
199	     *
200	     * @param owner           the newly mapped and normalized owner being created
201	     * @param sharesHousehold whether the request opted in to joining an existing household
202	     */
203	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
204	        // Identify any existing owners who share a household (same last name and address,
205	        // compared case-insensitively with collapsed whitespace) with the owner being created.
206	        List<Owner> householdMembers = sameHouseholdOwners(owner);
207	        // When opting in and joining an existing household, link the new owner to it so all
208	        // owners of the household share one stable 'householdId'.
209	        if (sharesHousehold && !householdMembers.isEmpty()) {
210	            linkToHousehold(owner, householdMembers);
211	        }
212	        // Record the size of this owner's household after this create, fixed at creation time.
213	        owner.setHouseholdSize(householdSize(owner, householdMembers));
214	    }
215	
216	    /**
217	     * Links a newly created owner that opts into an existing household to it, by sharing one stable
218	     * {@code householdId} across the new owner and every existing member. The identifier is derived
219	     * from the owner's last name and address (the same value every member of the household derives),
220	     * assigned to the new owner, and assigned to every existing member that does not already carry
221	     * it, persisting each member it updates. Called only when the request opts in via
222	     * {@code sharesHousehold} and at least one existing member was found.
223	     *
224	     * @param owner            the newly created owner joining the household
225	     * @param householdMembers the existing owners that share the owner's household
226	     */
227	    private void linkToHousehold(Owner owner, List<Owner> householdMembers) {
228	        String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
229	        owner.setHouseholdId(householdId);
230	        for (Owner member : householdMembers) {
231	            if (!householdId.equals(member.getHouseholdId())) {
232	                member.setHouseholdId(householdId);
233	                this.clinicService.saveOwner(member);
234	            }
235	        }
236	    }
237	
238	    /**
239	     * Computes the size of a newly created owner's household after this create, i.e. the number of
240	     * owners sharing this owner's {@code householdId} once it is persisted. An owner that shares an
241	     * existing household counts the matched members plus itself; an owner without a shared household
242	     * is a household of one. Fixed at creation time.
243	     *
244	     * @param owner            the owner being created, with its household already resolved
245	     * @param householdMembers the existing owners that share the owner's household
246	     * @return the household size to record on the owner
247	     */
248	    private int householdSize(Owner owner, List<Owner> householdMembers) {
249	        return owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1;
250	    }
251	
252	    /**
253	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
254	     * has already been resolved: the namesake count, the per-city customer code, the membership
255	     * number derived from that customer code and the registration year, and the bulk-signup warning
256	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
257	     * here keeps {@link #addOwner} focused on the high-level create sequence.
258	     *
259	     * @param owner the owner being created, already normalized and with its household resolved
260	     */
261	    private void assignDerivedFields(Owner owner) {
262	        // Record how many existing owners already share this owner's first and last name
263	        // (compared case-insensitively) before this create, fixed at creation time.
264	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
265	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
266	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
267	        // time.
268	        owner.setCustomerCode(customerCode(owner));
269	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
270	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
271	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
272	        // Flag the create when more than 80 owners have already been created on this owner's
273	        // (adjusted business-day) registration date, fixed at creation time.
274	        owner.setBulkSignupWarning(
275	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
276	    }
277	
278	    /**
279	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
280	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
281	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
282	     * the former separate telephone, email and household duplicate checks: two owners collide only
283	     * when their whole keys are equal, and members of one household with different telephones have
284	     * different keys and are both allowed.
285	     *
286	     * @param owner the owner being created, already normalized and with its household resolved
287	     */
288	    private void rejectWhenIdentityInUse(Owner owner) {
289	        String identityKey = owner.getIdentityKey();
290	        boolean inUse = existingOwners()
291	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
292	        if (inUse) {
293	            throw new DuplicateIdentityException(
294	                "An owner with identity key " + identityKey + " already exists");
295	        }
296	    }
297	
298	    /**
299	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
300	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
301	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
302	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
303	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
304	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
305	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
306	     * possible duplicate. Both values are fixed at creation time.
307	     *
308	     * @param owner the owner being created, already normalized and confirmed not a hard duplicate
309	     */
310	    private void assignPossibleDuplicate(Owner owner) {
311	        Integer matchId = owner.getPostcode() == null ? null : existingOwners()
312	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
313	            .map(Owner::getId)
314	            .min(Integer::compareTo)
315	            .orElse(null);
316	        owner.setPossibleDuplicate(matchId != null);
317	        owner.setPossibleDuplicateOf(matchId);
318	    }
319	
320	    /**
321	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
322	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
323	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
324	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
325	     *
326	     * @param existing an existing owner to compare against
327	     * @param owner    the owner being created
328	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
329	     */
330	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
331	        return existing.getPostcode() != null
332	            && existing.getPostcode().equals(owner.getPostcode())
333	            && existing.getLastName() != null
334	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
335	            && existing.getTelephone() != null
336	            && !existing.getTelephone().equals(owner.getTelephone());
337	    }
338	
339	    /**
340	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
341	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
342	     *
343	     * @param owner the owner being created
344	     */
345	    private void rejectWhenDailyLimitReached(Owner owner) {
346	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
347	            throw new DailyOwnerLimitExceededException(
348	                "The maximum number of owners that may be created today has already been reached");
349	        }
350	    }
351	
352	    /**
353	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
354	     * or more owners, with 409 Conflict.
355	     *
356	     * @param owner the owner being created
357	     */
358	    private void rejectWhenCityAtCapacity(Owner owner) {
359	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
360	            throw new CityCapacityExceededException(
361	                "The city " + owner.getCity() + " already contains the maximum number of owners");
362	        }
363	    }
364	
365	    /**
366	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
367	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
368	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
369	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
370	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
371	     * server's current date. Canonicalising the address here, before the household checks read it,
372	     * ensures duplicate detection and the shared household id both compare the normalized form.
373	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
374	     * duplicate, household and customer-code rules.
375	     *
376	     * @param owner the newly mapped owner to canonicalize
377	     */
378	    private void normalizeOwnerFields(Owner owner) {
379	        // Normalize the address on create so it is stored and returned in canonical form and every
380	        // later comparison (household duplicate detection and the shared household id) uses it.
381	        // A value that is blank after normalization is rejected with 400.
382	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
383	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
384	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
385	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
386	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
387	        // Store the (already syntactically validated) email lower-cased so it is persisted and
388	        // returned in canonical form. A missing email is left untouched.
389	        owner.setEmail(normalizeEmail(owner.getEmail()));
390	        // Validate the optional postcode against the fixed range for the city's region. A postcode
391	        // is checked only when present (it is optional); one out of range for the city's region is
392	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
393	        // value is left unchanged.
394	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
395	        // Reject a supplied registration date that is later than the server's current date with
396	        // 400, before any defaulting or business-day adjustment, so a future date is never
397	        // persisted regardless of how the roll-forward would move it.
398	        rejectFutureRegistrationDate(owner.getRegistrationDate());
399	        // Default the registration date to the server's current date when the client did not
400	        // supply one, then roll the effective date forward to a business day so a Saturday or
401	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
402	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
403	        // date-derived field (such as the membership number's year segment) and the per-day
404	        // create-limit are computed from.
405	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
406	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
407	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
408	    }
409	
410	    /**
411	     * Rejects a supplied registration date that is later than the server's current date with a
412	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
413	     * accepted, and a date on or before today is left for the normal defaulting and business-day
414	     * adjustment.
415	     *
416	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
417	     */
418	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
419	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
420	            throw new InvalidRegistrationDateException(
421	                "The supplied registration date " + registrationDate + " is later than the current date");
422	        }
423	    }
424	
425	    /**
426	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
427	     * following Monday, while a weekday is returned unchanged. Applied to the effective
428	     * registration date (whether supplied in the request or defaulted to the server date) so the
429	     * persisted registration date, every value derived from it and the per-day create-limit all
430	     * use the adjusted business day.
431	     *
432	     * @param date the effective registration date
433	     * @return the same date if it is a weekday, otherwise the following Monday
434	     */
435	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
436	        java.time.LocalDate adjusted = date;
437	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
438	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
439	            adjusted = adjusted.plusDays(1);
440	        }
441	        return adjusted;
442	    }
443	
444	    /**
445	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
446	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
447	     * syntactically valid address (rejecting anything else with 400).
448	     *
449	     * @param email the email value (may be {@code null})
450	     * @return the lower-cased email, or {@code null} if the input was {@code null}
451	     */
452	    private String normalizeEmail(String email) {
453	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
454	    }
455	
456	    /**
457	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
458	     * region derived from the owner's postcode (falling back to the city, via
459	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
460	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
461	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
462	     * owner's region and identity fields.
463	     *
464	     * @param owner the owner being created, already normalized
465	     * @return the formatted customer code
466	     */
467	    private String customerCode(Owner owner) {
468	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
469	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
470	        return region + "-" + hash8;
471	    }
472	
473	    /**
474	     * Streams the existing owners that the create-time rules match a new owner against. Every
475	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
476	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
477	     * own matching criterion rather than on how the existing owners are retrieved.
478	     *
479	     * @return a stream over all existing owners
480	     */
481	    private Stream<Owner> existingOwners() {
482	        return this.clinicService.findAllOwners().stream();
483	    }
484	
485	    /**
486	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
487	     * fix the per-city sequence of an owner's customer code at creation time.
488	     *
489	     * @param city the city of the owner being created
490	     * @return the number of existing owners in a matching city
491	     */
492	    private int countOwnersInCity(String city) {
493	        return (int) existingOwners()
494	            .filter(existing -> existing.getCity() != null
495	                && existing.getCity().equalsIgnoreCase(city))
496	            .count();
497	    }
498	
499	    /**
500	     * Counts the existing owners whose registration date is the given adjusted business day. Used
501	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
502	     * owners already carry that business day as their registration date.
503	     *
504	     * @param date the adjusted business-day registration date to match
505	     * @return the number of existing owners registered on that date
506	     */
507	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
508	        return (int) existingOwners()
509	            .filter(existing -> date.equals(existing.getRegistrationDate()))
510	            .count();
511	    }
512	
513	    /**
514	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
515	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
516	     *
517	     * @param customerCode     the owner's customer code
518	     * @param registrationDate the owner's registration date
519	     * @return the formatted membership number
520	     */
521	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
522	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
523	    }
524	
525	    /**
526	     * Returns the existing owners who share the given owner's household, i.e. have the same last
527	     * name and the same address. The comparison delegates to {@link HouseholdNormalizer} so that
528	     * values differing only in letter case or in incidental whitespace are treated as the same
529	     * household. Centralising how "the same household" is matched here keeps that definition in one
530	     * place for every caller.
531	     *
532	     * @param owner the owner being created
533	     * @return the existing owners in the owner's household (possibly empty)
534	     */
535	    private List<Owner> sameHouseholdOwners(Owner owner) {
536	        String householdKey = householdNormalizer.householdKey(owner.getLastName(), owner.getAddress());
537	        return existingOwners()
538	            .filter(existing -> householdNormalizer
539	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
540	            .toList();
541	    }
542	
543	    /**
544	     * Counts the existing owners who share the given first and last name, compared
545	     * case-insensitively. Used to fix an owner's namesake count at creation time.
546	     *
547	     * @param firstName the first name of the owner being created
548	     * @param lastName  the last name of the owner being created
549	     * @return the number of existing owners with a matching first and last name
550	     */
551	    private int countNamesakes(String firstName, String lastName) {
552	        return (int) existingOwners()
553	            .filter(existing -> existing.getFirstName() != null
554	                && existing.getFirstName().equalsIgnoreCase(firstName)
555	                && existing.getLastName() != null
556	                && existing.getLastName().equalsIgnoreCase(lastName))
557	            .count();
558	    }
559	
560	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
561	    @Override
562	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
563	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
564	        if (currentOwner == null) {
565	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
566	        }
567	        currentOwner.setAddress(ownerFieldsDto.getAddress());
568	        currentOwner.setCity(ownerFieldsDto.getCity());
569	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
570	        currentOwner.setLastName(ownerFieldsDto.getLastName());
571	        // Normalize the telephone to canonical E.164 form so it is stored and returned
572	        // consistently with create; an unformattable value is rejected with 400.
573	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
574	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
575	        this.clinicService.saveOwner(currentOwner);
576	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
577	    }
578	
579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Transactional
581	    @Override
582	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
583	        Owner owner = this.clinicService.findOwnerById(ownerId);
584	        if (owner == null) {
585	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
586	        }
587	        this.clinicService.deleteOwner(owner);
588	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Override
593	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
594	        Owner owner = this.clinicService.findOwnerById(ownerId);
595	        if (owner == null) {
596	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
597	        }
598	        HttpHeaders headers = new HttpHeaders();
599	        Pet pet = petMapper.toPet(petFieldsDto);
600	        owner.setId(ownerId);
601	        pet.setOwner(owner);
602	        pet.getType().setName(null);
603	        this.clinicService.savePet(pet);
604	        PetDto petDto = petMapper.toPetDto(pet);
605	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
606	            .buildAndExpand(pet.getId()).toUri());
607	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
613	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
614	        if (currentOwner != null) {
615	            Pet currentPet = this.clinicService.findPetById(petId);
616	            if (currentPet != null) {
617	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
618	                currentPet.setName(petFieldsDto.getName());
619	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
620	                this.clinicService.savePet(currentPet);
621	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
622	            }
623	        }
624	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
625	    }
626	
627	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
628	    @Override
629	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
630	        HttpHeaders headers = new HttpHeaders();
631	        Visit visit = visitMapper.toVisit(visitFieldsDto);
632	        Pet pet = new Pet();
633	        pet.setId(petId);
634	        visit.setPet(pet);
635	        this.clinicService.saveVisit(visit);
636	        VisitDto visitDto = visitMapper.toVisitDto(visit);
637	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
638	            .buildAndExpand(visit.getId()).toUri());
639	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
640	    }
641	
642	
643	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
644	    @Override
645	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
646	        Owner owner = this.clinicService.findOwnerById(ownerId);
647	        if (owner != null) {
648	            Pet pet = owner.getPet(petId);
649	            if (pet != null) {
650	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
651	            }
652	        }
653	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	    }
655	}
